132	// validDiscoveryURL accepts only absolute http/https URLs with a non-empty
133	// host and no userinfo, fragment or invalid port.
134	func validDiscoveryURL(raw string) bool {
135		if raw == "" || strings.Contains(raw, "#") {
136			return false
137		}
138		u, err := url.Parse(raw)
139		if err != nil {
140			return false
141		}
142		scheme := strings.ToLower(u.Scheme)
143		if scheme != "http" && scheme != "https" {
144			return false
145		}
146		if u.User != nil || u.Hostname() == "" {
147			return false
148		}
149		if port := u.Port(); port != "" {
150			n, err := strconv.Atoi(port)
151			if err != nil || n > 65535 {
152				return false
153			}
154		}
155		return true
156	}
