        cur, ok := s.series[sm.key]
        if !ok {
            cur = &series{name: sm.name, typ: sm.typ, labels: sm.labels}
            s.series[sm.key] = cur
        }
        var written float64
        switch sm.typ {
        case "counter":
            base, seen := s.scrapeBaseline[sm.key]
            var delta float64
            if !seen || sm.value < base {
                delta = sm.value
            } else {
                delta = sm.value - base
            }
            cur.value += delta
            s.scrapeBaseline[sm.key] = sm.value
            written = delta
        case "gauge":
            cur.value = sm.value
            written = sm.value
        }
        cur.history = append(cur.history, historyPoint{ts: ts, value: written})
    }
    return true
}
